source=source:sub(1,start-1)..[[local audit=read(ground..'/audit.json');local install=read(ground..'/install.json')
assert(audit.status=='passed' and audit.material_bindings_preserved and audit.map_sha256==install.map_sha256 and (prev.map_sha256==install.before_map_sha256 or prev.map_sha256==install.map_sha256 or prev.map_sha256==install.parent_map_sha256))
]]..source:sub(stop)
source=source:gsub("local target='E:/StreetSocialCityProduction/environment%-packages/'%.%.id","local target=ground..'/packages/'..id")
source=source:gsub("%[IO%.DriveInfo%]::new%('E'%)","[IO.DriveInfo]::new('C')")
source=source:gsub('Fresh cook after generated grass refinement, existing successful isolated E code host, new Stage/Archive; all ground asset hashes unchanged during cook','Fresh cook of level city geometry and five named campus gates, isolated E engine host, new C drive Stage/Archive; source assets unchanged during cook')
assert(load(source,'flat-campus-repackage'))()
